def _canonical_bytes(value: Any) -> bytes:
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def _digest_object(value: Any) -> str:
    return "sha256:" + sha256_hex(_canonical_bytes(value))


def _atomic_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    temporary.write_text(
        json.dumps(value, indent=2, ensure_ascii=False) + "\n", encoding="utf-8"
    )
    os.replace(temporary, path)


def _write_content_addressed_json(
    directory: Path, value: Any,
) -> tuple[Path, str]:
    """Create immutable JSON evidence and reuse only byte-identical content."""

    payload = (json.dumps(value, indent=2, ensure_ascii=False) + "\n").encode("utf-8")
    digest = "sha256:" + sha256_hex(payload)
    path = directory / f"{digest.split(':', 1)[1]}.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        with path.open("xb") as handle:
            handle.write(payload)
    except FileExistsError:
        if path.read_bytes() != payload:
            raise ValueError(f"content-addressed evidence collision: {path}")
    return path.resolve(), digest


def _write_content_addressed_bytes(
    directory: Path, payload: bytes, suffix: str,
) -> tuple[Path, str]:
    digest = "sha256:" + sha256_hex(payload)
    path = directory / f"{digest.split(':', 1)[1]}{suffix}"
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        with path.open("xb") as handle:
            handle.write(payload)
    except FileExistsError:
        if path.read_bytes() != payload:
            raise ValueError(f"content-addressed evidence collision: {path}")
    return path.resolve(), digest


def _git_checked(*args: str) -> str:
    cp = subprocess.run(
        ["git", *args], cwd=str(ROOT), capture_output=True, text=True, check=False
    )
    if cp.returncode != 0:
        raise RuntimeError(f"git {' '.join(args)} failed: {cp.stderr.strip()}")
    return cp.stdout.strip()


def _file_identity(path: Path) -> str:
    if not path.exists():
        return "missing"
    if path.is_file():
        return sha256_hex(path.read_bytes())
    return "directory"


def _git_status_snapshot() -> dict[str, str]:
    cp = subprocess.run(
        ["git", "-c", "core.quotepath=false", "status", "--porcelain=v1", "--untracked-files=all"],
        cwd=str(ROOT), capture_output=True, text=True, check=False,
    )
    if cp.returncode != 0:
        raise RuntimeError(f"git status failed: {cp.stderr.strip()}")
    result: dict[str, str] = {}
    for line in cp.stdout.splitlines():
        if len(line) < 4:
            continue
        path = line[3:]
        if " -> " in path:
            path = path.split(" -> ", 1)[1]
        normalized = path.replace("\\", "/")
        result[normalized] = f"{line[:2]}:{_file_identity(ROOT / normalized)}"
    return result


def _changed_status_paths(before: dict[str, str], after: dict[str, str]) -> list[str]:
    return sorted(
        path for path in set(before) | set(after) if before.get(path) != after.get(path)
    )


def _git_is_ancestor(ancestor: str, descendant: str) -> bool:
    completed = subprocess.run(
        ["git", "merge-base", "--is-ancestor", ancestor, descendant],
        cwd=str(ROOT), capture_output=True, check=False,
    )
    return completed.returncode == 0


def _git_path_bytes(commit: str, path: str) -> bytes | None:
    object_name = f"{commit}:{path}"
    exists = subprocess.run(
        ["git", "cat-file", "-e", object_name], cwd=str(ROOT),
        capture_output=True, check=False,
    )
    if exists.returncode != 0:
        return None
    completed = subprocess.run(
        ["git", "show", object_name], cwd=str(ROOT), capture_output=True, check=False,
    )
    if completed.returncode != 0:
        raise RuntimeError(f"git show failed for {object_name}")
    return completed.stdout


def _committed_delta(start_commit: str, result_commit: str) -> tuple[list[str], dict[str, str]]:
    """Bind the exact task delta; renames are intentionally deletion plus addition."""
    if not _git_is_ancestor(start_commit, result_commit):
        raise RuntimeError(
            f"task result {result_commit} does not descend from start {start_commit}"
        )
    completed = subprocess.run(
        [
            "git", "-c", "core.quotepath=false", "diff", "--no-renames",
            "--name-only", "-z", start_commit, result_commit,
        ],
        cwd=str(ROOT), capture_output=True, check=False,
    )
    if completed.returncode != 0:
        raise RuntimeError("git diff failed while binding the task delta")
    paths = sorted(
        item.decode("utf-8").replace("\\", "/")
        for item in completed.stdout.split(b"\0") if item
    )
    artifact_digests: dict[str, str] = {}
    for path in paths:
        result_bytes = _git_path_bytes(result_commit, path)
        if result_bytes is not None:
            artifact_digests[f"result-path:{path}"] = "sha256:" + sha256_hex(result_bytes)
            continue
        start_bytes = _git_path_bytes(start_commit, path)
        if start_bytes is None:
            raise RuntimeError(f"changed path is absent from both task commits: {path}")
        artifact_digests[f"deleted-path:{path}"] = "sha256:" + sha256_hex(start_bytes)
    return paths, artifact_digests


def _matches_allowed(path: str, patterns: list[str]) -> bool:
    normalized = path.replace("\\", "/")
    for raw in patterns:
        pattern = raw.replace("\\", "/")
        if pattern.startswith("$JC_REMEDIATION_STATE_ROOT"):
            continue
        if pattern.endswith("/**") and (
            normalized == pattern[:-3] or normalized.startswith(pattern[:-2])
        ):
            return True
        if fnmatch.fnmatchcase(normalized, pattern):
            return True
    return False


def _expanded_argv(argv: list[str], state_root: Path) -> list[str]:
    replacements = {
        "{python}": sys.executable,
        "{state_root}": str(state_root),
        "$JC_REMEDIATION_STATE_ROOT": str(state_root),
    }
    expanded: list[str] = []
    for value in argv:
        current = value
        for marker, replacement in replacements.items():
            current = current.replace(marker, replacement)
        expanded.append(current)
    if expanded[0].lower() == "codegraph":
        wrapper = shutil.which(expanded[0])
        if wrapper and wrapper.lower().endswith(".cmd"):
            installation = Path(wrapper).resolve().parent.parent
            node = installation / "node.exe"
            script = installation / "lib" / "dist" / "bin" / "codegraph.js"
            if node.is_file() and script.is_file():
                return [str(node), "--liftoff-only", str(script), *expanded[1:]]
    return expanded


def _stream_record(path: Path, payload: bytes) -> dict[str, Any]:
    path.write_bytes(payload)
    return {"path": str(path), "sha256": sha256_hex(payload), "bytes": len(payload)}


def _pytest_junit_path(argv: list[str]) -> Path | None:
    values: list[str] = []
    for index, value in enumerate(argv):
        if value == "--junitxml":
            if index + 1 >= len(argv):
                raise ValueError("--junitxml requires a path")
            values.append(argv[index + 1])
        elif value.startswith("--junitxml="):
            values.append(value.split("=", 1)[1])
    if len(values) > 1:
        raise ValueError("pytest command declares multiple JUnit reports")
    return Path(values[0]) if values else None


def _run_argv(
    argv: list[str], expected_exit_code: int, attempt_dir: Path,
    index: int, timeout_seconds: float, state_root: Path, *, cwd: Path = ROOT,
) -> dict[str, Any]:
    exact_argv = _expanded_argv(argv, state_root)
    junit_path = _pytest_junit_path(exact_argv)
    if junit_path is not None:
        junit_path = junit_path.resolve()
        evidence_root = (state_root.resolve() / "evidence").resolve()
        if not junit_path.is_relative_to(evidence_root):
            raise ValueError(f"pytest JUnit report escapes state evidence root: {junit_path}")
        junit_path.parent.mkdir(parents=True, exist_ok=True)
        junit_path.unlink(missing_ok=True)
    timed_out = False
    exit_code: int | None
    if "pytest" in exact_argv:
        execution_environment = _required_pytest_environment()
    else:
        execution_environment = os.environ.copy()
        if Path(exact_argv[0]).name.lower() in {"node", "node.exe"}:
            execution_environment.pop("NODE_OPTIONS", None)
            execution_environment.pop("NODE_PATH", None)
    execution_environment.update({
        "JC_REMEDIATION_STATE_ROOT": str(state_root),
        "PYTHONIOENCODING": "utf-8",
        "PYTHONUTF8": "1",
    })
    pinned_spec = state_root.resolve() / "inputs" / "legal-math-modeling"
    preflight_error = ""
    if "tests/unit/test_spec_shadow_harness.py" in exact_argv:
        checkout_problems = _companion_checkout_problems(pinned_spec)
        if checkout_problems:
            preflight_error = "; ".join(checkout_problems)
        else:
            execution_environment["LEGAL_MATH_MODELING_ROOT"] = str(pinned_spec)
    if preflight_error:
        exit_code = EXIT_GATE_FAIL
        stdout = b""
        stderr = preflight_error.encode("utf-8")
    else:
        try:
            cp = subprocess.run(
                exact_argv, cwd=str(cwd), capture_output=True, check=False,
                timeout=timeout_seconds, env=execution_environment,
            )
            exit_code = cp.returncode
            stdout = cp.stdout
            stderr = cp.stderr
        except subprocess.TimeoutExpired as exc:
            timed_out = True
            exit_code = None
            stdout = exc.stdout or b""
            stderr = exc.stderr or b""
            if isinstance(stdout, str):
                stdout = stdout.encode("utf-8", errors="replace")
            if isinstance(stderr, str):
                stderr = stderr.encode("utf-8", errors="replace")
        except OSError as exc:
            exit_code = 127
            stdout = b""
            stderr = str(exc).encode("utf-8", errors="replace")
    return {
        "argv": exact_argv,
        "expected_exit_code": expected_exit_code,
        "exit_code": exit_code,
        "timed_out": timed_out,
        "stdout": _stream_record(attempt_dir / f"stdout-{index:03d}.bin", stdout),
        "stderr": _stream_record(attempt_dir / f"stderr-{index:03d}.bin", stderr),
    }


def _evaluate_assertions(
    task: dict[str, Any], command_results: list[dict[str, Any]], state_root: Path
) -> list[dict[str, Any]]:
    results: list[dict[str, Any]] = []
    commands_ok = all(
        not item["timed_out"] and item["exit_code"] == item["expected_exit_code"]
        for item in command_results
    )
    tracked = set(_git_tracked_files())
    for assertion in task.get("completion_assertions", []):
        kind = assertion["kind"]
        detail = ""
        if kind == "all_commands_passed":
            ok = commands_ok
            detail = "all exit codes matched" if ok else "command failure or timeout"
        elif kind in {"path_exists", "path_absent"}:
            raw = assertion.get("path", "")
            path = Path(raw.replace("{state_root}", str(state_root)))
            if not path.is_absolute():
                path = ROOT / path
            exists = path.exists()
            ok = exists if kind == "path_exists" else not exists
            detail = f"{path} exists={exists}"
        elif kind in {"git_tracked", "git_untracked"}:
            path = assertion.get("path", "").replace("\\", "/")
            is_tracked = path in tracked
            ok = is_tracked if kind == "git_tracked" else not is_tracked
            detail = f"{path} tracked={is_tracked}"
        else:
            ok = False
            detail = "command assertions must be task argv so their output is receipted"
        results.append({"id": assertion["id"], "kind": kind, "ok": ok, "detail": detail})
    return results


def _receipt_digest(receipt: dict[str, Any]) -> str:
    unsigned = {key: value for key, value in receipt.items() if key != "receipt_digest"}
    return _digest_object(unsigned)


def _task_digest(task: dict[str, Any]) -> str:
    return _digest_object(task)


def _validate_stream(stream: dict[str, Any]) -> bool:
    path = Path(stream["path"])
    if not path.is_file():
        return False
    payload = path.read_bytes()
    return len(payload) == stream["bytes"] and sha256_hex(payload) == stream["sha256"]


def _declared_state_artifacts(
    command_results: list[dict[str, Any]], state_root: Path,
) -> dict[str, str]:
    """Recompute state evidence declared by receipted command stdout."""
    evidence_root = (state_root.resolve() / "evidence").resolve()
    artifacts: dict[str, str] = {}
    labels: set[str] = set()
    for command_index, command in enumerate(command_results, 1):
        stdout_path = Path(command["stdout"]["path"])
        payload = stdout_path.read_bytes().decode("utf-8", errors="strict")
        for line in payload.splitlines():
            if not line.startswith("JC_ARTIFACT\t"):
                continue
            fields = line.split("\t")
            if len(fields) != 4:
                raise ValueError("invalid JC_ARTIFACT field count")
            _, label, raw_path, digest = fields
            if not re.fullmatch(r"[a-z0-9][a-z0-9._-]*", label):
                raise ValueError(f"invalid JC_ARTIFACT label: {label}")
            if label in labels:
                raise ValueError(f"duplicate JC_ARTIFACT label: {label}")
            labels.add(label)
            if not DIGEST_V4_PATTERN.fullmatch(digest):
                raise ValueError(f"invalid JC_ARTIFACT digest grammar: {digest}")
            target = Path(raw_path).resolve(strict=True)
            if not target.is_file() or not target.is_relative_to(evidence_root):
                raise ValueError(f"JC_ARTIFACT escapes state evidence root: {target}")
            actual = "sha256:" + sha256_hex(target.read_bytes())
            if actual != digest:
                raise ValueError(
                    f"JC_ARTIFACT digest mismatch for {label}: {actual} != {digest}"
                )
            artifacts[f"state-artifact:{label}"] = digest
        junit_path = _pytest_junit_path(command.get("argv", []))
        if junit_path is not None:
            target = junit_path.resolve(strict=True)
            if not target.is_file() or not target.is_relative_to(evidence_root):
                raise ValueError(f"pytest JUnit report escapes state evidence root: {target}")
            artifacts[f"state-artifact:pytest-junit-{command_index:03d}"] = (
                "sha256:" + sha256_hex(target.read_bytes())
            )
    return artifacts


def _validate_git_binding(commit: str, tree: str) -> bool:
    cp = subprocess.run(
        ["git", "rev-parse", f"{commit}^{{tree}}"], cwd=str(ROOT),
        capture_output=True, text=True, check=False,
    )
    return cp.returncode == 0 and cp.stdout.strip() == tree


def _state_artifact_recovery_replay(
    receipt: dict[str, Any], state_root: Path, recovery_attempt: int,
) -> tuple[dict[str, Any], list[list[str]]]:
    """Return the exact historical task and its only permitted replay argv projection."""

    old_plan_bytes = _git_path_bytes(receipt["result_commit"], "remediation/v4/tasks.json")
    if old_plan_bytes is None:
        raise ValueError("result commit does not contain the historical plan")
    old_plan = json.loads(old_plan_bytes.decode("utf-8"))
    old_task = next(
        (
            item for item in old_plan.get("tasks", [])
            if item.get("id") == receipt.get("task_id")
        ),
        None,
    )
    if (
        old_task is None
        or old_task.get("id") != "W1-06"
        or _task_digest(old_task) != receipt.get("task_digest")
        or receipt.get("status") != "COMPLETED"
        or recovery_attempt <= receipt.get("attempt", 0)
    ):
        raise ValueError("historical W1-06 task definition or recovery attempt is invalid")
    commands = receipt.get("command_results")
    raw_argv = old_task.get("argv")
    exit_codes = old_task.get("expected_exit_codes")
    if (
        not isinstance(commands, list)
        or not isinstance(raw_argv, list)
        or not isinstance(exit_codes, list)
        or len(commands) != 3
        or len(commands) != len(raw_argv)
        or len(commands) != len(exit_codes)
    ):
        raise ValueError("historical W1-06 replay must contain its exact three lanes")

    replay_evidence = (
        state_root / "evidence" / "state-recoveries" / "W1-06" / str(recovery_attempt)
    )
    replay_tmp = state_root / "tmp" / "state-recoveries" / "W1-06" / str(recovery_attempt)
    replay_argvs: list[list[str]] = []
    for index, (command, task_argv, expected_exit_code) in enumerate(
        zip(commands, raw_argv, exit_codes), 1
    ):
        original_argv = _expanded_argv(task_argv, state_root)
        if (
            command.get("argv") != original_argv
            or command.get("expected_exit_code") != expected_exit_code
            or command.get("exit_code") != expected_exit_code
            or command.get("timed_out") is not False
        ):
            raise ValueError("lost receipt does not bind the historical W1-06 argv")
        replay_argv = list(original_argv)
        junit_flags = 0
        basetemp_flags = 0
        position = 0
        while position < len(replay_argv):
            value = replay_argv[position]
            if value in {"--junitxml", "--basetemp"}:
                if position + 1 >= len(replay_argv):
                    raise ValueError(f"{value} requires a path")
                if value == "--junitxml":
                    junit_flags += 1
                    replacement = replay_evidence / f"pytest-junit-{index:03d}.xml"
                else:
                    basetemp_flags += 1
                    replacement = replay_tmp
                replay_argv[position + 1] = str(replacement)
                position += 2
                continue
            if value.startswith("--junitxml="):
                junit_flags += 1
                replay_argv[position] = (
                    "--junitxml=" + str(replay_evidence / f"pytest-junit-{index:03d}.xml")
                )
            elif value.startswith("--basetemp="):
                basetemp_flags += 1
                replay_argv[position] = "--basetemp=" + str(replay_tmp)
            position += 1
        if junit_flags > 1 or basetemp_flags > 1:
            raise ValueError("historical replay argv contains duplicate redirected flags")
        replay_argvs.append(replay_argv)
    if (
        sum(_pytest_junit_path(argv) is not None for argv in replay_argvs) != 1
        or sum(
            value == "--basetemp" or value.startswith("--basetemp=")
            for argv in replay_argvs
            for value in argv
        ) != 1
    ):
        raise ValueError("historical W1-06 replay must redirect one JUnit and one basetemp")
    return old_task, replay_argvs


def _state_artifact_recovery_matches(
    receipt: dict[str, Any],
    recorded: dict[str, str],
    observed: dict[str, str],
    recovery: dict[str, Any] | None,
    state_root: Path,
) -> bool:
    """Accept one lost JUnit only when the next append-only receipt proves replay."""

    differing = [key for key in recorded if recorded.get(key) != observed.get(key)]
    if (
        recovery is None
        or receipt.get("task_id") != "W1-06"
        or recovery.get("task_id") != "W1-06"
        or set(recorded) != set(observed)
        or len(differing) != 1
        or not differing[0].startswith("state-artifact:pytest-junit-")
    ):
        return False
    artifact_key = differing[0]
    try:
        command_index = int(artifact_key.rsplit("-", 1)[1])
        artifact_path = _pytest_junit_path(
            receipt["command_results"][command_index - 1]["argv"]
        )
        old_task, replay_argvs = _state_artifact_recovery_replay(
            receipt, state_root, recovery["attempt"]
        )
        recovery_commands = recovery["command_results"]
        if len(recovery_commands) != len(replay_argvs):
            return False
        for command, expected_argv, expected_exit_code in zip(
            recovery_commands, replay_argvs, old_task["expected_exit_codes"]
        ):
            if (
                command.get("argv") != expected_argv
                or command.get("expected_exit_code") != expected_exit_code
                or command.get("exit_code") != expected_exit_code
                or command.get("timed_out") is not False
                or not _validate_stream(command["stdout"])
                or not _validate_stream(command["stderr"])
            ):
                return False
        replay_reports = _structured_test_reports(
            recovery_commands, runner_version=recovery["runner_version"]
        )
        if (
            recovery.get("test_reports") != replay_reports
            or _w1_06_test_report_problems(replay_reports)
        ):
            return False
        replay_state = _declared_state_artifacts(recovery_commands, state_root)
        recorded_replay_state = {
            key: value for key, value in recovery["artifact_digests"].items()
            if key.startswith("state-artifact:")
        }
        if recorded_replay_state != replay_state or artifact_key not in replay_state:
            return False
        record_digest = recovery["artifact_digests"]["recovery-record"]
        if not isinstance(record_digest, str) or DIGEST_V4_PATTERN.fullmatch(record_digest) is None:
            return False
        record_path = (
            state_root / "evidence" / "state-recoveries"
            / f"{record_digest.split(':', 1)[1]}.json"
        )
        record_bytes = record_path.read_bytes()
        record = json.loads(record_bytes.decode("utf-8"))
    except (
        IndexError, KeyError, OSError, TypeError, UnicodeError, ValueError,
        json.JSONDecodeError,
    ):
        return False
    if artifact_path is None:
        return False
    expected_record = {
        "schema_version": "jc/state-artifact-recovery/1.0",
        "task_id": receipt["task_id"],
        "lost_attempt": receipt["attempt"],
        "lost_receipt_digest": receipt["receipt_digest"],
        "artifact_key": artifact_key,
        "artifact_path": str(artifact_path.resolve()),
        "expected_digest": recorded[artifact_key],
        "observed_digest": observed[artifact_key],
        "action": "REPLAY_AT_RESULT_COMMIT",
        "replay_commit": receipt["result_commit"],
        "replay_attempt": recovery["attempt"],
        "replay_argv_digest": _digest_object(replay_argvs),
        "replacement_digest": replay_state[artifact_key],
    }
    recovery_assertion = next(
        (
            item for item in recovery.get("completion_assertions", [])
            if item.get("id") == "runner-state-artifact-recovery"
        ),
        None,
    )
    return (
        "sha256:" + sha256_hex(record_bytes) == record_digest
        and record == expected_record
        and recovery.get("status") == "COMPLETED"
        and recovery.get("task_id") == receipt["task_id"]
        and isinstance(recovery.get("attempt"), int)
        and recovery["attempt"] > receipt["attempt"]
        and recovery.get("task_digest") == receipt.get("task_digest")
        and recovery.get("runner_version") in KNOWN_RUNNER_VERSIONS
        and recovery.get("run_id") == receipt.get("run_id")
        and recovery.get("input_receipt_digests") == receipt.get("input_receipt_digests")
        and recovery.get("start_commit") == receipt["start_commit"]
        and recovery.get("start_tree") == receipt.get("start_tree")
        and recovery.get("result_commit") == receipt["result_commit"]
        and recovery.get("result_tree") == receipt.get("result_tree")
        and recovery.get("changed_paths") == receipt.get("changed_paths")
        and recovery.get("allowlist") == receipt.get("allowlist")
        and recovery.get("previous_receipt_digest") == receipt["receipt_digest"]
        and recovery.get("artifact_digests", {}).get("recovery-source-receipt")
        == receipt["receipt_digest"]
        and recovery.get("artifact_digests", {}).get("recovery-loss-observation")
        == _digest_object({"recorded": recorded, "observed": observed})
        and isinstance(recovery_assertion, dict)
        and recovery_assertion.get("ok") is True
    )


def _receipt_history(task_id: str, state_root: Path) -> list[dict[str, Any]]:
    task_dir = state_root / "tasks" / task_id
    if not task_dir.exists():
        return []
    validator = Draft202012Validator(json.loads(RECEIPT_SCHEMA.read_text(encoding="utf-8")))
    receipts: list[dict[str, Any]] = []
    previous: str | None = None
    attempt_dirs = sorted(
        (path for path in task_dir.iterdir() if path.is_dir() and path.name.isdigit()),
        key=lambda path: int(path.name),
    )
    raw_receipts: dict[int, dict[str, Any]] = {}
    for attempt_dir in attempt_dirs:
        receipt_path = attempt_dir / "receipt.json"
        if receipt_path.is_file():
            try:
                raw_receipts[int(attempt_dir.name)] = json.loads(
                    receipt_path.read_text(encoding="utf-8")
                )
            except (OSError, UnicodeError, json.JSONDecodeError) as exc:
                raise ValueError(f"receipt unreadable: {receipt_path}: {exc}") from exc
    previous_attempt = 0
    for index, attempt_dir in enumerate(attempt_dirs):
        receipt_path = attempt_dir / "receipt.json"
        if not receipt_path.is_file():
            interruption = attempt_dir / "interrupted.json"
            if interruption.exists():
                continue
            if index != len(attempt_dirs) - 1:
                raise ValueError(f"receipt missing before a later attempt: {receipt_path}")
            if not interruption.exists():
                _atomic_json(interruption, {
                    "status": "INTERRUPTED", "detected_at": _iso_now(),
                    "detail": "attempt directory existed without receipt; preserved for audit",
                })
            continue
        receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
        errors = list(validator.iter_errors(receipt))
        if errors:
            raise ValueError(f"invalid receipt schema {receipt_path}: {errors[0].message}")
        attempt_number = int(attempt_dir.name)
        if receipt["task_id"] != task_id or receipt["attempt"] != attempt_number or attempt_number <= previous_attempt:
            raise ValueError(f"receipt identity mismatch: {receipt_path}")
        if receipt["runner_version"] not in KNOWN_RUNNER_VERSIONS:
            raise ValueError(f"unsupported receipt runner version: {receipt_path}")
        if receipt["previous_receipt_digest"] != previous:
            raise ValueError(f"receipt chain broken: {receipt_path}")
        if receipt["receipt_digest"] != _receipt_digest(receipt):
            raise ValueError(f"receipt digest mismatch: {receipt_path}")
        if not _validate_git_binding(receipt["start_commit"], receipt["start_tree"]):
            raise ValueError(f"start commit/tree mismatch: {receipt_path}")
        if not _validate_git_binding(receipt["result_commit"], receipt["result_tree"]):
            raise ValueError(f"result commit/tree mismatch: {receipt_path}")
        expected_paths, expected_artifacts = _committed_delta(
            receipt["start_commit"], receipt["result_commit"]
        )
        if receipt["changed_paths"] != expected_paths:
            raise ValueError(f"changed path binding mismatch: {receipt_path}")
        recorded_delta_artifacts = {
            key: value for key, value in receipt["artifact_digests"].items()
            if key.startswith("result-path:") or key.startswith("deleted-path:")
        }
        if recorded_delta_artifacts != expected_artifacts:
            raise ValueError(f"artifact digest binding mismatch: {receipt_path}")
        for command in receipt["command_results"]:
            if not _validate_stream(command["stdout"]) or not _validate_stream(command["stderr"]):
                raise ValueError(f"stdout/stderr digest mismatch: {receipt_path}")
        expected_state_artifacts = _declared_state_artifacts(
            receipt["command_results"], state_root
        )
        recorded_state_artifacts = {
            key: value for key, value in receipt["artifact_digests"].items()
            if key.startswith("state-artifact:")
        }
        state_recovered = _state_artifact_recovery_matches(
            receipt,
            recorded_state_artifacts,
            expected_state_artifacts,
            next(
                (
                    raw_receipts[number]
                    for number in sorted(raw_receipts)
                    if number > attempt_number
                ),
                None,
            ),
            state_root,
        )
        if recorded_state_artifacts != expected_state_artifacts and not state_recovered:
            raise ValueError(f"state artifact binding mismatch: {receipt_path}")
        must_rebuild_test_reports = (
            receipt["runner_version"] == RUNNER_VERSION
            or any(
                assertion["id"].startswith("runner-")
                for assertion in receipt["completion_assertions"]
            )
        )
        if (
            must_rebuild_test_reports
            and receipt["test_reports"] != _structured_test_reports(
                receipt["command_results"], runner_version=receipt["runner_version"]
            )
            and not state_recovered
        ):
            raise ValueError(f"structured test report binding mismatch: {receipt_path}")
        previous = receipt["receipt_digest"]
        previous_attempt = attempt_number
        receipts.append(receipt)
    return receipts


def _next_attempt(task_id: str, state_root: Path) -> int:
    task_dir = state_root / "tasks" / task_id
    attempts = [int(path.name) for path in task_dir.iterdir() if path.is_dir() and path.name.isdigit()] if task_dir.exists() else []
    return max(attempts, default=0) + 1


def _topological_tasks(plan: dict[str, Any]) -> list[dict[str, Any]]:
    tasks = plan["tasks"]
    by_id = {task["id"]: task for task in tasks}
    remaining = set(by_id)
    completed: set[str] = set()
    ordered: list[dict[str, Any]] = []
    while remaining:
        ready = [task for task in tasks if task["id"] in remaining and set(task["depends_on"]) <= completed]
        if not ready:
            raise ValueError("task DAG has a cycle or missing dependency")
        task = ready[0]
        ordered.append(task)
        completed.add(task["id"])
        remaining.remove(task["id"])
    return ordered


def _task_start_commit(
    task: dict[str, Any], completed_receipts: dict[str, dict[str, Any]],
    run_baseline_commit: str,
) -> str:
    """Return the latest linear execution frontier, not only a DAG dependency.

    Direct dependency receipts govern readiness and input identity.  Commits in
    the single remediation worktree are necessarily linear, so a later sibling
    task must start after every previously completed task instead of rebinding
    those sibling commits as its own delta.
    """

    latest = run_baseline_commit
    for completed in completed_receipts.values():
        candidate = completed["result_commit"]
        if _git_is_ancestor(latest, candidate):
            latest = candidate
        elif not _git_is_ancestor(candidate, latest):
            raise ValueError(
                f"task {task['id']} completed commits are not linearly ordered"
            )
    for dependency in task["depends_on"]:
        dependency_commit = completed_receipts[dependency]["result_commit"]
        if not _git_is_ancestor(dependency_commit, latest):
            raise ValueError(
                f"task {task['id']} dependency {dependency} is outside the execution frontier"
            )
    return latest


def _subject_digest(task: dict[str, Any], state_root: Path) -> str:
    identities: list[dict[str, str]] = []
    for raw in task["approval"]["subject_paths"]:
        normalized_raw = raw.replace("\\", "/")
        state_bound = normalized_raw == "$JC_REMEDIATION_STATE_ROOT" or normalized_raw.startswith(
            "$JC_REMEDIATION_STATE_ROOT/"
        )
        expanded = raw.replace("$JC_REMEDIATION_STATE_ROOT", str(state_root))
        base = Path(expanded)
        matches = list(ROOT.glob(expanded)) if not base.is_absolute() else list(base.parent.glob(base.name))
        if not matches:
            identities.append({"path": normalized_raw, "sha256": "MISSING"})
        labeled_matches: list[tuple[str, Path]] = []
        for path in matches:
            resolved = path.resolve()
            if state_bound:
                relative = resolved.relative_to(state_root.resolve())
                label = "$JC_REMEDIATION_STATE_ROOT"
                if relative != Path("."):
                    label += "/" + relative.as_posix()
            else:
                try:
                    label = resolved.relative_to(ROOT.resolve()).as_posix()
                except ValueError:
                    label = resolved.as_posix()
            labeled_matches.append((label, path))
        for label, path in sorted(labeled_matches, key=lambda item: item[0]):
            identities.append({"path": label, "sha256": _file_identity(path)})
    return _digest_object({"task_id": task["id"], "subject": task["approval"]["subject"], "artifacts": identities})


def _gate_request(
    task: dict[str, Any], state_root: Path, run_id: str,
    start_commit: str, input_receipts: dict[str, str],
) -> dict[str, Any]:
    approval = task["approval"]
    subject_digest = _subject_digest(task, state_root)
    request_fields = {
        "schema_version": "jc/remediation-v4-gate-request/2.0", "run_id": run_id,
        "task_id": task["id"], "gate_id": approval["gate_id"], "kind": task["mode"],
        "task_digest": _task_digest(task), "start_commit": start_commit,
        "input_receipt_digests": input_receipts,
        "subject": approval["subject"], "subject_digest": subject_digest,
        "required_roles": approval["required_roles"], "allowed_scopes": approval["allowed_scopes"],
        "minimum_signers": approval["minimum_signers"],
        "separation_of_duties": approval["separation_of_duties"],
    }
    request_dir = state_root / "requests" / task["id"]
    request_path = request_dir / f"{subject_digest.split(':', 1)[1]}.json"
    if request_path.exists():
        try:
            cached = json.loads(request_path.read_text(encoding="utf-8"))
            issued_at = cached["issued_at"]
            _parse_time(issued_at)
        except (AttributeError, KeyError, OSError, TypeError, UnicodeError, ValueError, json.JSONDecodeError) as exc:
            raise ValueError(f"cached gate request is invalid: {request_path}: {exc}") from exc
        rebuilt = {**request_fields, "issued_at": issued_at}
        rebuilt["request_digest"] = _digest_object(rebuilt)
        if cached != rebuilt:
            raise ValueError(
                f"cached gate request does not match current task/state or self-digest: {request_path}"
            )
        return cached
    request = {**request_fields, "issued_at": _iso_now()}
    request["request_digest"] = _digest_object(request)
    _atomic_json(request_path, request)
    return request


def _parse_time(value: str) -> datetime:
    parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError("timestamp must include an explicit UTC offset")
    return parsed.astimezone(timezone.utc)


def _approval_payload(approval: dict[str, Any]) -> bytes:
    return _canonical_bytes({key: value for key, value in approval.items() if key != "signature"})


def _evidence_record(path: Path, payload: dict[str, Any]) -> dict[str, Any]:
    try:
        raw_digest = "sha256:" + sha256_hex(path.read_bytes())
    except OSError as exc:
        raise ValueError(f"evidence is unreadable: {path}: {exc}") from exc
    return {"payload": payload, "path": str(path.resolve()), "raw_digest": raw_digest}


def _authority_source_record(source: dict[str, Any]) -> dict[str, str]:
    locator = Path(source["locator"])
    if not locator.is_absolute():
        raise ValueError("authority_source.locator must be an absolute file path")
    try:
        resolved = locator.resolve(strict=True)
        if resolved != locator or not resolved.is_file():
            raise ValueError("authority_source.locator must be a canonical file path")
        raw_digest = "sha256:" + sha256_hex(resolved.read_bytes())
    except OSError as exc:
        raise ValueError(f"authority source is unreadable: {locator}: {exc}") from exc
    if raw_digest != source["sha256"]:
        raise ValueError("authority source digest mismatch")
    return {"path": str(resolved), "raw_digest": raw_digest}


def _valid_approvals(task: dict[str, Any], request: dict[str, Any], state_root: Path) -> list[dict[str, Any]]:
    evidence_kind = task["approval"]["evidence_kind"]
    if evidence_kind == "USER_DIRECTIVE":
        directive_dir = state_root / "directives" / task["id"]
        if not directive_dir.is_dir():
            return []
        try:
            schema = json.loads(USER_DIRECTIVE_SCHEMA.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise ValueError(f"user directive schema is unreadable: {exc}") from exc
        validator = Draft202012Validator(schema)
        accepted_directives: list[dict[str, Any]] = []
        seen_keys: set[str] = set()
        now = datetime.now(timezone.utc)
        for path in sorted(directive_dir.glob("*.json")):
            try:
                directive = json.loads(path.read_text(encoding="utf-8"))
                if list(validator.iter_errors(directive)):
                    continue
                signer = directive["signer"]
                key_id = signer["key_id"]
                if key_id in seen_keys:
                    continue
                if (
                    directive["run_id"] != request["run_id"]
                    or directive["gate_id"] != request["gate_id"]
                    or directive["task_id"] != task["id"]
                    or directive["request_digest"] != request["request_digest"]
                    or directive["subject_digest"] != request["subject_digest"]
                    or directive["decision"] != "APPROVE"
                    or directive["scope"] not in task["approval"]["allowed_scopes"]
                    or signer["scope"] != directive["scope"]
                    or signer["role"] not in task["approval"]["required_roles"]
                    or _parse_time(directive["issued_at"]) > now
                ):
                    continue
                authority_source = _authority_source_record(directive["authority_source"])
                evidence = _evidence_record(path, directive)
            except (AttributeError, KeyError, OSError, TypeError, UnicodeError, ValueError, json.JSONDecodeError):
                continue
            seen_keys.add(key_id)
            evidence["authority_source"] = authority_source
            accepted_directives.append(evidence)
        return accepted_directives
    if evidence_kind == "EXTERNAL_ARTIFACT":
        return []
    trust_path = state_root / "trust" / "trusted_keys.json"
    if not trust_path.is_file():
        return []
    trusted = json.loads(trust_path.read_text(encoding="utf-8"))
    keys = {item["key_id"]: item for item in trusted.get("keys", [])}
    approval_dir = state_root / "approvals" / task["id"]
    if not approval_dir.is_dir():
        return []
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
    accepted: list[dict[str, Any]] = []
    seen_keys: set[str] = set()
    now = datetime.now(timezone.utc)
    schema = json.loads(APPROVAL_SCHEMA.read_text(encoding="utf-8"))
    validator = Draft202012Validator(schema)
    for path in sorted(approval_dir.glob("*.json")):
        try:
            candidate = json.loads(path.read_text(encoding="utf-8"))
            if list(validator.iter_errors(candidate)):
                continue
            signer = candidate["signer"]
            key = keys.get(signer["key_id"])
            if not key or signer["key_id"] in seen_keys:
                continue
            if candidate["task_id"] != task["id"] or candidate["gate_id"] != request["gate_id"]:
                continue
            if candidate["request_digest"] != request["request_digest"] or candidate.get("subject_digest") != request["subject_digest"]:
                continue
            if (
                candidate["decision"] != "APPROVE"
                or _parse_time(candidate["issued_at"]) > now
                or _parse_time(candidate["expires_at"]) <= now
            ):
                continue
            if signer["role"] not in request["required_roles"] or signer["scope"] not in request["allowed_scopes"]:
                continue
            if signer["role"] not in key.get("roles", []) or signer["scope"] not in key.get("scopes", []):
                continue
            signature = candidate["signature"]
            if signature["algorithm"] != "Ed25519" or signature.get("public_key_id", signer["key_id"]) != signer["key_id"]:
                continue
            public_key = Ed25519PublicKey.from_public_bytes(base64.b64decode(key["public_key_base64"]))
            public_key.verify(base64.b64decode(signature["value"]), _approval_payload(candidate))
        except Exception:
            continue
        seen_keys.add(signer["key_id"])
        accepted.append(_evidence_record(path, candidate))
    if request["separation_of_duties"] and len(seen_keys) != len(accepted):
        return []
    return accepted


def _gate_evidence_artifacts(
    task: dict[str, Any], request: dict[str, Any], approvals: list[dict[str, Any]],
    state_root: Path,
) -> dict[str, str]:
    request_path = (
        state_root / "requests" / task["id"]
        / f"{request['subject_digest'].split(':', 1)[1]}.json"
    )
    try:
        request_bytes = request_path.read_bytes()
        if json.loads(request_bytes.decode("utf-8")) != request:
            raise ValueError("gate request changed after validation")
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError(f"gate request evidence is unreadable: {exc}") from exc
    artifacts = {
        "request": request["request_digest"],
        "request-raw": "sha256:" + sha256_hex(request_bytes),
    }
    for approval in approvals:
        payload = approval["payload"]
        key_id = payload["signer"]["key_id"]
        path = Path(approval["path"])
        try:
            raw_digest = "sha256:" + sha256_hex(path.read_bytes())
        except OSError as exc:
            raise ValueError(f"approval evidence is unreadable: {path}: {exc}") from exc
        if raw_digest != approval["raw_digest"]:
            raise ValueError(f"approval evidence changed after validation: {path}")
        artifacts[f"approval:{key_id}"] = _digest_object(payload)
        artifacts[f"approval-raw:{key_id}"] = raw_digest
        authority_source = approval.get("authority_source")
        if authority_source is not None:
            authority_path = Path(authority_source["path"])
            try:
                authority_digest = "sha256:" + sha256_hex(authority_path.read_bytes())
            except OSError as exc:
                raise ValueError(
                    f"authority source evidence is unreadable: {authority_path}: {exc}"
                ) from exc
            if authority_digest != authority_source["raw_digest"]:
                raise ValueError(f"authority source changed after validation: {authority_path}")
            artifacts[f"authority-source:{key_id}"] = authority_digest
    return artifacts


def _gate_approval_assertion(
    task: dict[str, Any], approvals: list[dict[str, Any]],
) -> dict[str, Any]:
    return {
        "id": "approval-policy", "kind": "evidence_policy", "ok": True,
        "detail": (
            f"{len(approvals)} {task['approval']['evidence_kind']} "
            "evidence item(s) bound to request and subject"
        ),
    }


def _complete_gate_task(
    task: dict[str, Any], request: dict[str, Any], approvals: list[dict[str, Any]],
    state_root: Path, run_id: str, input_receipts: dict[str, str],
    history: list[dict[str, Any]], start_commit: str,
) -> dict[str, Any]:
    attempt = _next_attempt(task["id"], state_root)
    attempt_dir = state_root / "tasks" / task["id"] / str(attempt)
    attempt_dir.mkdir(parents=True, exist_ok=False)
    commit = _git_checked("rev-parse", "HEAD")
    tree = _git_checked("rev-parse", "HEAD^{tree}")
    if task["mode"] == "MIXED":
        receipt_start_commit = start_commit
        receipt_start_tree = _git_checked("rev-parse", f"{start_commit}^{{tree}}")
        changed_paths, committed_artifacts = _committed_delta(start_commit, commit)
        violations = [
            path for path in changed_paths
            if not _matches_allowed(path, task["allowed_paths"])
        ]
        status = "COMPLETED" if changed_paths and not violations else "FAILED"
        if violations:
            status = "SCOPE_VIOLATION"
    else:
        receipt_start_commit = commit
        receipt_start_tree = tree
        changed_paths = []
        committed_artifacts = {}
        violations = []
        status = "COMPLETED"
    gate_artifacts = _gate_evidence_artifacts(task, request, approvals, state_root)
    assertions = [_gate_approval_assertion(task, approvals)]
    if task["mode"] == "MIXED":
        assertions.append({
            "id": "runner-mixed-committed-delta", "kind": "artifact_binding",
            "ok": bool(changed_paths),
            "detail": (
                f"{len(changed_paths)} committed path(s) bound from dependency start"
                if changed_paths else "MIXED task produced no committed delta"
            ),
        })
    receipt = {
        "schema_version": "jc/remediation-v4-receipt/2.1", "task_digest": _task_digest(task), "run_id": run_id,
        "task_id": task["id"], "attempt": attempt, "status": status,
        "input_receipt_digests": input_receipts,
        "start_commit": receipt_start_commit, "start_tree": receipt_start_tree,
        "result_commit": commit, "result_tree": tree,
        "command_results": [], "changed_paths": changed_paths,
        "allowlist": {"allowed": not violations, "violations": violations}, "test_reports": [],
        "artifact_digests": {**committed_artifacts, **gate_artifacts},
        "completion_assertions": assertions,
        "previous_receipt_digest": history[-1]["receipt_digest"] if history else None,
        "runner_version": RUNNER_VERSION,
    }
    _write_receipt(attempt_dir, receipt)
    return receipt


def _write_receipt(attempt_dir: Path, receipt: dict[str, Any]) -> None:
    receipt["receipt_digest"] = _receipt_digest(receipt)
    schema = json.loads(RECEIPT_SCHEMA.read_text(encoding="utf-8"))
    errors = list(Draft202012Validator(schema).iter_errors(receipt))
    if errors:
        raise ValueError(f"runner produced invalid receipt: {errors[0].message}")
    path = attempt_dir / "receipt.json"
    with path.open("x", encoding="utf-8") as handle:
        json.dump(receipt, handle, indent=2, ensure_ascii=False)
        handle.write("\n")


def _structured_test_reports(
    command_results: list[dict[str, Any]], *, runner_version: str = RUNNER_VERSION,
) -> list[dict[str, Any]]:
    try:
        report_format = STRUCTURED_TEST_REPORT_FORMAT_BY_RUNNER_VERSION[runner_version]
    except KeyError as exc:
        raise ValueError(f"unsupported structured report runner version: {runner_version!r}") from exc
    reports: list[dict[str, Any]] = []
    for index, item in enumerate(command_results, 1):
        argv = item["argv"]
        kind: str | None = None
        if "pytest" in argv:
            kind = "pytest"
        elif any(Path(value).name == "jcs_node_oracle.mjs" for value in argv):
            kind = "node-oracle"
        elif (
            report_format >= 3
            and len(argv) >= 2
            and argv[-2:] == ["verify-wave", "W0-04"]
        ):
            kind = "pytest-governance"
        if kind is None:
            continue
        stdout_path = Path(item["stdout"]["path"])
        stdout_text = stdout_path.read_text(encoding="utf-8", errors="replace")
        if report_format >= 5:
            stdout_text = re.sub(r"\x1b\[[0-?]*[ -/]*[@-~]", "", stdout_text)
        report: dict[str, Any] = {
            "command_index": index,
            "kind": kind,
            "exit_code": item["exit_code"],
        }
        report.update({
            "stdout_sha256": item["stdout"]["sha256"],
            "stderr_sha256": item["stderr"]["sha256"],
        })
        if kind == "pytest":
            summary_text = stdout_text
            if report_format >= 5:
                summary_lines = [
                    line.strip()
                    for line in stdout_text.splitlines()
                    if re.search(
                        r"(?:^|\s)\d+ (?:passed|failed|errors?|skipped|xfailed|xpassed)"
                        r"(?:\s|,|$)",
                        line,
                    )
                ]
                report["terminal_summaries"] = len(summary_lines)
                summary_text = summary_lines[0] if len(summary_lines) == 1 else ""
            passed = re.search(r"(?:^|\s)(\d+) passed(?:\s|,|$)", summary_text)
            if passed:
                report["passed"] = int(passed.group(1))
            if report_format >= 5:
                outcome_patterns = {
                    "failed": r"(?:^|\s)(\d+) failed(?:\s|,|$)",
                    "errors": r"(?:^|\s)(\d+) errors?(?:\s|,|$)",
                    "skipped": r"(?:^|\s)(\d+) skipped(?:\s|,|$)",
                    "xfailed": r"(?:^|\s)(\d+) xfailed(?:\s|,|$)",
                    "xpassed": r"(?:^|\s)(\d+) xpassed(?:\s|,|$)",
                }
                for field, pattern in outcome_patterns.items():
                    match = re.search(pattern, summary_text)
                    report[field] = int(match.group(1)) if match else 0
                collection = re.search(
                    r"(?:^|\s)(\d+) errors? during collection(?:\s|,|$)", stdout_text
                )
                report["collection_errors"] = int(collection.group(1)) if collection else 0
                junit_path = _pytest_junit_path(argv)
                if junit_path is not None:
                    try:
                        counts, cases = _junit_evidence(junit_path)
                        case_ids = sorted(
                            f"{item.attrib.get('classname', '')}::{item.attrib.get('name', '')}"
                            for item in cases
                        )
                        report.update({
                            "junit_valid": True,
                            "junit_sha256": sha256_hex(junit_path.read_bytes()),
                            "junit_tests": counts["tests"],
                            "junit_skipped": counts["skipped"],
                            "junit_failures": counts["failures"],
                            "junit_errors": counts["errors"],
                            "junit_cases": len(case_ids),
                            "junit_unique_cases": len(set(case_ids)),
                            "junit_case_ids_digest": _digest_object(case_ids),
                        })
                    except (OSError, ET.ParseError, ValueError):
                        report["junit_valid"] = False
        elif kind == "node-oracle":
            for field in ("positive", "negative", "canonical_bytes"):
                match = re.search(rf"(?:^|\s){field}=(\d+)(?:\s|$)", stdout_text)
                if match:
                    report[field] = int(match.group(1))
            if report_format >= 4:
                for field in ("float_tokens", "duplicate_key"):
                    match = re.search(rf"(?:^|\s){field}=([a-z-]+)(?:\s|$)", stdout_text)
                    if match:
                        report[field] = match.group(1)
            runtime = re.search(r"(?:^|\s)runtime=(v\d+\.\d+\.\d+)(?:\s|$)", stdout_text)
            if runtime:
                report["runtime"] = runtime.group(1)
        else:
            summary = re.search(
                r"test governance skeleton OK: (?P<suites>\d+) suites; "
                r"(?P<audits>\d+) audit groups registered; "
                r"(?P<rewrites>\d+) rewrites queued; "
                r"(?P<required>\d+) required governance tests passed; "
                r"(?P<red>\d+) future obligations explicitly RED; "
                r"0 skip/xfail/xpass/collection errors",
                stdout_text,
            )
            if summary is None:
                continue
            report.update({
                "suites": int(summary.group("suites")),
                "audit_groups": int(summary.group("audits")),
                "rewrites": int(summary.group("rewrites")),
                "required_passed": int(summary.group("required")),
                "future_red": int(summary.group("red")),
                "bypass_or_collection_errors": 0,
            })
            for line in stdout_text.splitlines():
                fields = line.split("\t")
                if len(fields) == 4 and fields[:2] == ["JC_ARTIFACT", "w0-04-required-tests"]:
                    report["evidence_label"] = fields[1]
                    report["evidence_sha256"] = fields[3]
            if "evidence_sha256" not in report:
                continue
        reports.append(report)
    return reports


def _w1_01_test_report_problems(test_reports: list[dict[str, Any]]) -> list[str]:
    """Require exact executable evidence for the W1-01 pytest and Node lanes."""

    problems: list[str] = []
    pytest_reports = [report for report in test_reports if report.get("kind") == "pytest"]
    node_reports = [report for report in test_reports if report.get("kind") == "node-oracle"]
    if len(pytest_reports) != 1 or (
        pytest_reports[0].get("exit_code"), pytest_reports[0].get("passed")
    ) != (0, 38):
        problems.append("W1-01 pytest report is not exactly 38 passed")
    if len(node_reports) != 1:
        problems.append("W1-01 must bind exactly one Node oracle report")
        return problems
    node_report = node_reports[0]
    runtime = node_report.get("runtime")
    runtime_match = re.fullmatch(r"v(?P<major>\d+)\.\d+\.\d+", str(runtime))
    if runtime_match is None or int(runtime_match.group("major")) not in {22, 24}:
        problems.append("W1-01 Node oracle runtime must be major 22 or 24")
    expected_node = {
        "exit_code": 0,
        "positive": 9,
        "negative": 16,
        "canonical_bytes": 295,
        "float_tokens": "raw-lexical",
        "duplicate_key": "declaration-only",
    }
    for field, expected in expected_node.items():
        if node_report.get(field) != expected:
            problems.append(
                f"W1-01 Node oracle {field} drifted: "
                f"{node_report.get(field)!r} != {expected!r}"
            )
    return problems


